INSERT INTO public.vocabulary_examples (id, vocabulary_id, korean_sentence, vietnamese_translation) VALUES ('4d2a02bd-6f6f-490b-8d0f-6c844cff0a8b', '66aaa124-11dc-418e-889d-6f731114af0e', '장점이 있는 반면에 단점도 존재한다.', 'Có ưu điểm nhưng ngược lại cũng tồn tại nhược điểm.') ON CONFLICT (id) DO NOTHING;
