INSERT INTO public.vocabulary_examples (id, vocabulary_id, korean_sentence, vietnamese_translation) VALUES ('4a44aab3-4549-4e5b-8d2f-c662552ef450', 'fba4b618-d539-4133-8237-930a5cefe69b', '자신의 의견을 논리적으로 주장했다.', 'Đã khẳng định quan điểm của mình một cách chặt chẽ theo logic.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g01', 'N 은/는', 'Đứng sau danh từ để nhấn mạnh chủ đề của câu hoặc thể hiện sự so sánh, đối chiếu.', 'Sơ cấp 1', 'Khác với 이/가 (nhấn mạnh tân ngữ/chủ ngữ cụ thể), 은/는 nhấn mạnh thông tin mới phía sau vị ngữ.', 'Danh từ có patchim + 은 / Không patchim + 는', 'Dùng nhầm 은 cho từ không có patchim (ví dụ: 저은 -> sai, phải là 저는).', '[{"korean":"저는 베트남 사람입니다.","vietnamese":"Tôi là người Việt Nam."},{"korean":"이 책은 재미있어요.","vietnamese":"Cuốn sách này rất hay."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g02', 'N 이/가', 'Gắn sau danh từ để biểu thị danh từ đó là chủ ngữ thực hiện hành động hoặc trạng thái.', 'Sơ cấp 1', 'Thường đi kèm với 있다/없다, 좋다/싫다, 아니다 hoặc khi xuất hiện chủ ngữ mới lần đầu.', 'Danh từ có patchim + 이 / Không patchim + 가', 'Nhầm lẫn giữa 은/는 và 이/가 khi miêu tả thời tiết (phải dùng 날씨가 좋아요).', '[{"korean":"비가 와요.","vietnamese":"Trời đang mưa."},{"korean":"시간이 없어요.","vietnamese":"Tôi không có thời gian."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g03', 'N 을/를', 'Gắn sau danh từ chịu tác động trực tiếp của ngoại động từ.', 'Sơ cấp 1', 'Trong khẩu ngữ đời thường, 을/를 có thể được lược bỏ nếu câu văn đã rõ nghĩa.', 'Danh từ có patchim + 을 / Không patchim + 를', 'Dùng 을/를 với nội động từ hoặc tính từ (ví dụ: 한국어를 좋아요 -> Sai, phải là 한국어가 좋아요).', '[{"korean":"밥을 먹어요.","vietnamese":"Tôi ăn cơm."},{"korean":"한국어를 배워요.","vietnamese":"Tôi học tiếng Hàn."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g04', 'N 이에요/예요', 'Đuôi câu thân mật lịch sự dùng để định nghĩa hoặc giới thiệu danh từ.', 'Sơ cấp 1', 'Tương đương với 입니다 ở phong cách trang trọng.', 'Có patchim + 이에요 / Không patchim + 예요', 'Nhầm giữa 이에요 và 예요 với các từ kết thúc bằng nguyên âm.', '[{"korean":"저는 학생이에요.","vietnamese":"Tôi là học sinh."},{"korean":"여기는 학교예요.","vietnamese":"Đây là trường học."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g05', 'N이/가 있어요/없어요', 'Diễn tả sự tồn tại hoặc sở hữu một đồ vật, người hoặc thời gian.', 'Sơ cấp 1', 'Cũng dùng để chỉ sự hiện diện ở một địa điểm nào đó (N에 있어요).', 'Danh từ + 이/가 + 있어요/없어요', 'Dùng tiểu từ 을/를 trước 있어요/없어요 (Sai).', '[{"korean":"한국 친구가 있어요.","vietnamese":"Tôi có bạn người Hàn Quốc."},{"korean":"돈이 없어요.","vietnamese":"Tôi không có tiền."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g06', '안 / V-지 않다', 'Diễn tả hành động hoặc trạng thái không xảy ra do ý chí của chủ thể.', 'Sơ cấp 1', 'Với động từ 하다, đặt 안 trước 하다 (ví dụ: 공부 안 해요).', '안 + Động từ/Tính từ HOẶC Gốc ĐT/TT + -지 않아요', 'Dùng 안 với tính từ phức tạp hoặc nhầm sang 못 (không thể).', '[{"korean":"오늘은 학교에 안 가요.","vietnamese":"Hôm nay tôi không đến trường."},{"korean":"이 음식은 맵지 않아요.","vietnamese":"Món này không cay."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g07', 'V-고 싶어요', 'Thể hiện mong muốn, nguyện vọng của người nói ở ngôi thứ nhất.', 'Sơ cấp 1', 'Chỉ đi với động từ, không gắn trực tiếp với tính từ.', 'Gốc động từ + -고 싶어요 (Ngôi 3: -고 싶어해요)', 'Dùng -고 싶어요 cho ngôi thứ ba (Anh ấy muốn đi -> phải dùng 가고 싶어해요).', '[{"korean":"한국에 여행 가고 싶어요.","vietnamese":"Tôi muốn đi du lịch Hàn Quốc."},{"korean":"커피를 마시고 싶어요.","vietnamese":"Tôi muốn uống cà phê."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g08', 'V-아/어야 해요', 'Biểu thị nghĩa vụ, bổn phận hoặc việc bắt buộc phải làm.', 'Sơ cấp 2', '-아/어야 되다 thường dùng trong văn nói, 하다 dùng trong cả văn viết.', 'Gốc ĐT chia theo nguyên âm + -아/어야 해요 (hoặc 하다/되다)', 'Chia sai nguyên âm khi kết thúc bằng đuôi bất quy tắc ㅂ hoặc ㄷ.', '[{"korean":"내일 시험이 있어서 공부해야 해요.","vietnamese":"Mai có bài thi nên tôi phải học bài."},{"korean":"약속 시간에 늦지 않아야 해요.","vietnamese":"Không được đến muộn giờ hẹn."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g09', 'V-(으)려고 하다', 'Diễn tả ý định, kế hoạch trong tương lai gần của chủ ngữ.', 'Sơ cấp 2', 'Không dùng đuôi này với câu mệnh lệnh (-(으)세요) hoặc rủ rê (-(으)ㅂ시다).', 'Có patchim + 으려고 하다 / Không patchim + 려고 하다', 'Nhầm lẫn với -(으)러 가다 (chỉ mục đích di chuyển).', '[{"korean":"이번 주말에 한국 영화를 보려고 해요.","vietnamese":"Cuối tuần này tôi định xem phim Hàn."},{"korean":"새 노트북을 사려고 해요.","vietnamese":"Tôi định mua một chiếc laptop mới."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g10', 'V/A-기 때문에', 'Nêu rõ nguyên nhân, lý do khách quan dẫn đến kết quả ở vế sau.', 'Trung cấp 1', 'Mang sắc thái trang trọng, lập luận rõ ràng hơn -(으)니까.', 'Gốc ĐT/TT + -기 때문에 / Danh từ + -때문에', 'Không dùng vế sau là câu mệnh lệnh hoặc rủ rê.', '[{"korean":"비가 오기 때문에 길이 많이 막혀요.","vietnamese":"Bởi vì trời mưa nên đường tắc nhiều."},{"korean":"바쁜 일 때문에 연락을 못 했어요.","vietnamese":"Vì bận việc nên tôi đã không thể liên lạc được."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.grammar_points (id, pattern, meaning, level, usage_notes, formula, common_mistakes, examples) VALUES ('g11', 'V/A-(으)ㄴ/는 것 같다', 'Phỏng đoán nhẹ nhàng hoặc biểu đạt ý kiến cá nhân lịch sự, không khẳng định gay gắt.', 'Trung cấp 1', 'Là cấu trúc được người Hàn sử dụng nhiều bậc nhất trong giao tiếp để tránh nói quá thẳng thừng.', 'Hiện tại ĐT: -는 것 같다 / Quá khứ ĐT: -(으)ㄴ 것 같다 / Tính từ: -(으)ㄴ 것 같다', 'Nhầm lẫn thì thời gian khi chia động từ quá khứ và hiện tại.', '[{"korean":"밖에 비가 오는 것 같아요.","vietnamese":"Hình như ngoài trời đang mưa."},{"korean":"이 옷이 저한테 조금 작은 것 같아요.","vietnamese":"Dường như chiếc áo này hơi chật với tôi."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, lesson_id, exercise_type, prompt, options, correct_answer, explanation, xp_reward) VALUES ('5d359559-1311-4053-8e79-347b0d3fa91b', NULL, 'multiple_choice', 'Từ nào sau đây có nghĩa là "Học sinh"?', '["선생님","학생","의사","회사원"]'::jsonb, '학생', '학생 (haksaeng) là "Học sinh", có gốc từ chữ Hán [學生]. 선생님 là giáo viên, 의사 là bác sĩ.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, lesson_id, exercise_type, prompt, options, correct_answer, explanation, xp_reward) VALUES ('3c1e90d2-ec9a-47c6-8ec2-28a250b1f3c9', NULL, 'multiple_choice', 'Điền tiểu từ thích hợp: "저는 베트남 사람____."', '["이에요","예요","은","를"]'::jsonb, '이에요', '사람 kết thúc bằng patchim "ㅁ" nên đi với "이에요".', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, lesson_id, exercise_type, prompt, options, correct_answer, explanation, xp_reward) VALUES ('7dc17e66-851a-4f05-8054-217a69c764b4', NULL, 'fill_blank', 'Điền từ tiếng Hàn chào hỏi trang trọng: "감사_____ (Cảm ơn)"', NULL, '합니다', '감사합니다 (gamsahamnida) là cách nói cảm ơn trang trọng chuẩn mực.', 15) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, lesson_id, exercise_type, prompt, options, correct_answer, explanation, xp_reward) VALUES ('1c1313d9-82ca-4402-8c3e-825060a70920', NULL, 'multiple_choice', 'Chọn âm đọc đúng của từ "학교" (Trường học):', '["hak-gyo","hak-saeng","sik-dang","do-seo-gwan"]'::jsonb, 'hak-gyo', '학교 được phiên âm là hak-gyo, âm Hán là Học Hiệu.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, lesson_id, exercise_type, prompt, options, correct_answer, explanation, xp_reward) VALUES ('aea25984-fa46-4edf-80e6-ef72960a24b2', NULL, 'translation', 'Dịch câu sau sang tiếng Hàn: "Tôi muốn uống nước."', '["물을 마시고 싶어요.","밥을 먹고 싶어요.","물을 마셨어요.","물이 없어요."]'::jsonb, '물을 마시고 싶어요.', 'Nước = 물, uống = 마시다, cấu trúc muốn = -고 싶어요.', 20) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.listening_items (id, title, audio_url, transcript, vietnamese_translation, level, questions) VALUES ('4782ae1b-8bf3-4f97-815f-e426b89da023', 'Hội thoại 1: Chào hỏi lần đầu gặp gỡ', '', '안녕하세요? 저는 민수예요. 만나서 반가워요.', 'Xin chào bạn? Tôi là Minsoo. Rất vui được gặp bạn.', 'Sơ cấp 1', '[{"question":"Người nói trong đoạn hội thoại tên là gì?","options":["민수 (Minsoo)","지훈 (Jihoon)","영희 (Younghee)","민호 (Minho)"],"correctAnswer":"민수 (Minsoo)","explanation":"Trong audio, nhân vật tự giới thiệu rõ ràng: \"저는 민수예요\" (Tôi là Minsoo)."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.listening_items (id, title, audio_url, transcript, vietnamese_translation, level, questions) VALUES ('b925d80d-f6b0-4b86-8827-a3640bccd52f', 'Hội thoại 2: Gọi món ăn tại nhà hàng', '', '여기 김치찌개 하나하고 불고기 일 인분 주세요.', 'Ở đây cho tôi xin 1 canh kim chi và 1 suất thịt nướng Bulgogi với ạ.', 'Sơ cấp 1', '[{"question":"Khách hàng đã gọi những món ăn nào?","options":["Kimchi jjigae và Bulgogi","Bibimbap và Kimbap","Mì lạnh và Thịt nướng","Canh sườn và Cơm trộn"],"correctAnswer":"Kimchi jjigae và Bulgogi","explanation":"Khách hàng nói: \"김치찌개 하나하고 불고기 일 인분\" (1 canh kim chi và 1 phần bulgogi)."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.listening_items (id, title, audio_url, transcript, vietnamese_translation, level, questions) VALUES ('e5b72766-2391-41b8-826f-8806a8014f1e', 'Hội thoại 3: Hỏi đường đến ga tàu điện ngầm', '', '실례지만, 서울역 지하철역이 어디에 있어요? 저쪽으로 곧장 가시면 오른쪽에 있어요.', 'Xin lỗi, ga tàu điện ngầm Seoul nằm ở đâu vậy ạ? Đi thẳng về hướng kia là nó nằm ở bên tay phải.', 'Sơ cấp 2', '[{"question":"Ga tàu điện ngầm nằm ở phía nào khi đi thẳng?","options":["Bên tay phải (오른쪽)","Bên tay trái (왼쪽)","Bên trong tòa nhà","Dưới tầng hầm thứ 2"],"correctAnswer":"Bên tay phải (오른쪽)","explanation":"Người hướng dẫn nói: \"오른쪽에 있어요\" (Ở bên tay phải)."}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.speaking_items (id, scenario, korean_sentence, romaja, vietnamese_meaning) VALUES ('3b8504e2-c5ac-4d34-8214-8e0797216bcc', 'restaurant', '여기 주문할게요! 비빔밥 하나 주세요.', 'yeogi jumunhalgeyo! bibimbap hana juseyo.', 'Cho tôi gọi món! Cho tôi một phần cơm trộn bibimbap nhé.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.speaking_items (id, scenario, korean_sentence, romaja, vietnamese_meaning) VALUES ('b18d3b42-9d1f-42e8-81ba-9a1458fa5916', 'shopping', '이거 얼마예요? 조금만 깎아 주세요.', 'igeo eolmayeyo? jogeumman kkakka juseyo.', 'Cái này bao nhiêu tiền ạ? Bớt cho tôi một chút nhé.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.speaking_items (id, scenario, korean_sentence, romaja, vietnamese_meaning) VALUES ('d589c577-7a60-45e2-865d-46a4dbf4efde', 'directions', '실례지만, 화장실이 어디에 있어요?', 'sillyejiman, hwajangsiri eodie isseoyo?', 'Xin lỗi làm phiền, nhà vệ sinh ở đâu vậy ạ?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.speaking_items (id, scenario, korean_sentence, romaja, vietnamese_meaning) VALUES ('031ef6d7-100a-4d3e-8e33-3ce4c587cea9', 'introduction', '안녕하세요, 저는 베트남에서 온 응우옌입니다.', 'annyeonghaseyo, jeoneun beteunameseoon eung-uyen-imnida.', 'Xin chào, tôi là Nguyễn đến từ Việt Nam.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.speaking_items (id, scenario, korean_sentence, romaja, vietnamese_meaning) VALUES ('386ae69c-ff7a-4f74-83be-ed582f6aef5e', 'interview', '회사 발전을 위해 최선을 다해 노력하겠습니다.', 'hoesa baljeoneul wihae choeseoneul dahae noryeokhagessseumnida.', 'Tôi sẽ nỗ lực hết mình vì sự phát triển của công ty.') ON CONFLICT (id) DO NOTHING;
